// ---------------------------------------------------------------------------
// AI Summary Dialog
// ---------------------------------------------------------------------------

interface AISummaryDialogProps {
  item: FeedItem | null;
  open: boolean;
  onClose: () => void;
}

function AISummaryDialog({ item, open, onClose }: AISummaryDialogProps) {
  const { toast } = useToast();
  const [summary, setSummary] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    if (!open || !item) return;

    if (item.ai_summary) {
      setSummary(item.ai_summary);
      return;
    }

    // Generate via local Ollama
    setLoading(true);
    setSummary(null);

    const prompt = `You are a cybersecurity analyst. Generate a brief threat intelligence summary.
TITLE: ${item.title}
CATEGORY: ${item.category}
SEVERITY: ${item.severity}
EXCERPT: ${item.excerpt ?? "N/A"}

Provide:
1. What this threat is (2-3 sentences)
2. Who is affected
3. Key indicators or actions to take
4. Source article: ${item.link}`;

    const fetchSummary = async () => {
      try {
        let text = "";
        if (GROQ_KEY) {
          const res = await fetch("https://api.groq.com/openai/v1/chat/completions", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${GROQ_KEY}`,
            },
            body: JSON.stringify({
              model: GROQ_CHAT_MODEL,
              messages: [
                { role: "system", content: "You are a cybersecurity analyst. Be concise and actionable." },
                { role: "user", content: prompt },
              ],
              max_tokens: 400,
              temperature: 0.3,
              stream: false,
            }),
            signal: AbortSignal.timeout(15000),
          });
          if (!res.ok) throw new Error(`Groq ${res.status}`);
          const data = await res.json();
          text = data.choices?.[0]?.message?.content ?? "";
        } else {
          const res = await fetch("/api/ollama/api/generate", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ model: "llama3.2:3b", prompt, stream: false }),
            signal: AbortSignal.timeout(20000),
          });
          if (!res.ok) throw new Error(`Ollama ${res.status}`);
          const data = await res.json();
          text = data.response ?? "";
        }
        setSummary(text || "No summary returned.");
      } catch (err) {
        setSummary(null);
        toast({
          title: "AI generation failed",
          description: err instanceof Error ? err.message : "Could not reach AI service.",
          variant: "destructive",
        });
      } finally {
        setLoading(false);
      }
    };
    fetchSummary();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, item?.id]);

  function handleCopy() {
    if (!summary) return;
    navigator.clipboard.writeText(summary).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  }

  function handleClose() {
    setSummary(null);
    setLoading(false);
    setCopied(false);
    onClose();
  }

  return (
    <Dialog open={open} onOpenChange={(v) => !v && handleClose()}>
      <DialogContent className="bg-[#0a0f1e] border border-white/10 text-white max-w-2xl w-full">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-cyan-400 text-base font-semibold">
            <Sparkles className="w-4 h-4" />
            AI Threat Summary
          </DialogTitle>
        </DialogHeader>

        {item && (
          <div className="space-y-4">
            <p className="text-sm font-semibold text-white/90 leading-snug">
              {item.title}
            </p>

            <div className="flex items-center gap-2">
              <Badge
                className={`text-xs border ${SEV_BADGE[item.severity.toLowerCase()] ?? "bg-gray-500/15 text-gray-400 border-gray-500/40"}`}
              >
                {item.severity.toUpperCase()}
              </Badge>
              <Badge className="text-xs border bg-white/5 text-white/50 border-white/10">
                {item.category}
              </Badge>
            </div>

            <div className="min-h-[120px]">
              {loading && (
                <div className="flex flex-col items-center justify-center gap-3 py-10">
                  <Loader2 className="w-6 h-6 text-cyan-400 animate-spin" />
                  <p className="text-sm text-white/50">
                    Generating summary with llama3.2:3b…
                  </p>
                </div>
              )}

              {!loading && summary && (
                <ScrollArea className="max-h-72 pr-2">
                  <p className="text-sm text-white/80 leading-relaxed whitespace-pre-wrap">
                    {summary}
                  </p>
                </ScrollArea>
              )}

              {!loading && !summary && (
                <p className="text-sm text-white/40 italic">
                  No summary available.
                </p>
              )}
            </div>

            <div className="flex items-center gap-2 pt-1 border-t border-white/10">
              <Button
                asChild
                size="sm"
                className="bg-cyan-500/10 text-cyan-400 border border-cyan-500/30 hover:bg-cyan-500/20"
              >
                <a href={item.link} target="_blank" rel="noopener noreferrer">
                  <ExternalLink className="w-3.5 h-3.5 mr-1.5" />
                  Read Full Article
                </a>
              </Button>

              <Button
                size="sm"
                variant="ghost"
                className="text-white/50 hover:text-white/80 border border-white/10 hover:border-white/20"
                onClick={handleCopy}
                disabled={!summary}
              >
                {copied ? (
                  <>
                    <Check className="w-3.5 h-3.5 mr-1.5 text-green-400" />
                    Copied
                  </>
                ) : (
                  <>
                    <Copy className="w-3.5 h-3.5 mr-1.5" />
                    Copy
                  </>
                )}
              </Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

