// ---------------------------------------------------------------------------
// Feed Tab
// ---------------------------------------------------------------------------

interface FeedTabProps {
  userEmail: string | null;
}

function FeedTab({ userEmail: _userEmail }: FeedTabProps) {
  const { toast } = useToast();
  const [items, setItems] = useState<FeedItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [newCount, setNewCount] = useState(0);
  const [pendingItems, setPendingItems] = useState<FeedItem[]>([]);
  const [search, setSearch] = useState("");
  const [sevFilter, setSevFilter] = useState("all");
  const [catFilter, setCatFilter] = useState("all");
  const [summaryItem, setSummaryItem] = useState<FeedItem | null>(null);
  const [dialogOpen, setDialogOpen] = useState(false);
  const latestIdRef = useRef<string | null>(null);
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const fetchItems = useCallback(async (isBackground = false) => {
    const { data, error } = await supabase
      .from("threat_items")
      .select("id, title, link, severity, category, published_at, ai_summary, excerpt")
      .order("published_at", { ascending: false })
      .limit(100);

    if (error) {
      if (!isBackground) {
        toast({
          title: "Failed to load feed",
          description: error.message,
          variant: "destructive",
        });
      }
      return;
    }

    const fetched = (data ?? []) as FeedItem[];

    if (!isBackground) {
      setItems(fetched);
      latestIdRef.current = fetched[0]?.id ?? null;
      setLoading(false);
    } else {
      // Background poll — check for new items
      if (fetched.length > 0 && fetched[0].id !== latestIdRef.current) {
        const currentIds = new Set(items.map((i) => i.id));
        const fresh = fetched.filter((i) => !currentIds.has(i.id));
        if (fresh.length > 0) {
          setPendingItems(fetched);
          setNewCount(fresh.length);
        }
      }
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items, toast]);

  useEffect(() => {
    fetchItems(false);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    pollRef.current = setInterval(() => fetchItems(true), POLL_INTERVAL);
    return () => {
      if (pollRef.current) clearInterval(pollRef.current);
    };
  }, [fetchItems]);

  function applyPendingItems() {
    setItems(pendingItems);
    latestIdRef.current = pendingItems[0]?.id ?? null;
    setPendingItems([]);
    setNewCount(0);
  }

  const categories = useMemo(() => {
    const cats = Array.from(new Set(items.map((i) => i.category).filter(Boolean)));
    return cats.sort();
  }, [items]);

  const filtered = useMemo(() => {
    return items.filter((item) => {
      const matchSearch =
        !search ||
        item.title.toLowerCase().includes(search.toLowerCase()) ||
        (item.excerpt ?? "").toLowerCase().includes(search.toLowerCase());
      const matchSev =
        sevFilter === "all" || item.severity.toLowerCase() === sevFilter;
      const matchCat =
        catFilter === "all" || item.category === catFilter;
      return matchSearch && matchSev && matchCat;
    });
  }, [items, search, sevFilter, catFilter]);

  function openSummary(item: FeedItem) {
    setSummaryItem(item);
    setDialogOpen(true);
  }

  return (
    <div className="space-y-4">
      {/* Stats */}
      <StatsBar items={items} />

      {/* New items banner */}
      {newCount > 0 && (
        <button
          onClick={applyPendingItems}
          className="w-full flex items-center justify-center gap-2 py-2.5 rounded-lg bg-cyan-500/10 border border-cyan-500/30 text-cyan-400 text-sm font-medium hover:bg-cyan-500/20 transition-colors"
        >
          <Bell className="w-4 h-4" />
          {newCount} new item{newCount > 1 ? "s" : ""} available — click to refresh
        </button>
      )}

      {/* Filter bar */}
      <div className="flex flex-wrap items-center gap-3">
        <div className="relative flex-1 min-w-[180px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-white/30" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search threats…"
            className="pl-9 h-9 bg-[#0a0f1e] border-white/10 text-white placeholder:text-white/30 focus-visible:ring-cyan-500/50 text-sm"
          />
        </div>

        {/* Severity dropdown */}
        <div className="relative">
          <select
            value={sevFilter}
            onChange={(e) => setSevFilter(e.target.value)}
            className="h-9 rounded-md bg-[#0a0f1e] border border-white/10 text-white text-sm px-3 pr-8 appearance-none focus:outline-none focus:ring-1 focus:ring-cyan-500/50 cursor-pointer"
          >
            <option value="all">All Severities</option>
            <option value="critical">Critical</option>
            <option value="high">High</option>
            <option value="medium">Medium</option>
            <option value="low">Low</option>
          </select>
          <ChevronDown className="absolute right-2 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-white/40 pointer-events-none" />
        </div>

        {/* Category dropdown */}
        <div className="relative">
          <select
            value={catFilter}
            onChange={(e) => setCatFilter(e.target.value)}
            className="h-9 rounded-md bg-[#0a0f1e] border border-white/10 text-white text-sm px-3 pr-8 appearance-none focus:outline-none focus:ring-1 focus:ring-cyan-500/50 cursor-pointer"
          >
            <option value="all">All Categories</option>
            {categories.map((cat) => (
              <option key={cat} value={cat}>
                {cat}
              </option>
            ))}
          </select>
          <ChevronDown className="absolute right-2 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-white/40 pointer-events-none" />
        </div>

        <span className="text-xs text-white/30 ml-auto hidden sm:block">
          {filtered.length} result{filtered.length !== 1 ? "s" : ""}
        </span>
      </div>

      {/* Feed items */}
      {loading ? (
        <div className="flex flex-col items-center justify-center gap-3 py-20">
          <Loader2 className="w-6 h-6 text-cyan-400 animate-spin" />
          <p className="text-sm text-white/40">Loading threat feed…</p>
        </div>
      ) : filtered.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 text-white/30">
          <Shield className="w-10 h-10 mb-3 opacity-30" />
          <p className="text-sm">No threats match your filters.</p>
        </div>
      ) : (
        <div className="grid gap-3">
          {filtered.map((item) => (
            <FeedCard key={item.id} item={item} onAISummary={openSummary} />
          ))}
        </div>
      )}

      <AISummaryDialog
        item={summaryItem}
        open={dialogOpen}
        onClose={() => setDialogOpen(false)}
      />
    </div>
  );
}

// ---------------------------------------------------------------------------
// AI Summaries Tab
