function AISummariesTab() {
  const { toast } = useToast();
  const [items, setItems] = useState<FeedItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [summaryItem, setSummaryItem] = useState<FeedItem | null>(null);
  const [dialogOpen, setDialogOpen] = useState(false);

  useEffect(() => {
    supabase
      .from("threat_items")
      .select("id, title, link, severity, category, published_at, ai_summary, excerpt")
      .not("ai_summary", "is", null)
      .order("published_at", { ascending: false })
      .limit(100)
      .then(({ data, error }) => {
        if (error) {
          toast({
            title: "Failed to load summaries",
            description: error.message,
            variant: "destructive",
          });
        } else {
          setItems((data ?? []) as FeedItem[]);
        }
        setLoading(false);
      });
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <Sparkles className="w-4 h-4 text-cyan-400" />
        <h2 className="text-sm font-semibold text-white/80">
          AI-Analyzed Threats
        </h2>
        {!loading && (
          <Badge className="text-xs border bg-cyan-500/10 text-cyan-400 border-cyan-500/30 ml-1">
            {items.length}
          </Badge>
        )}
      </div>

      {loading ? (
        <div className="flex flex-col items-center justify-center gap-3 py-20">
          <Loader2 className="w-6 h-6 text-cyan-400 animate-spin" />
          <p className="text-sm text-white/40">Loading AI summaries…</p>
        </div>
      ) : items.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 text-white/30">
          <Sparkles className="w-10 h-10 mb-3 opacity-30" />
          <p className="text-sm">No AI summaries available yet.</p>
        </div>
      ) : (
        <div className="grid gap-3">
          {items.map((item) => {
            const sev = item.severity.toLowerCase();
            return (
              <Card
                key={item.id}
                className={`bg-[#0a0f1e] border border-white/10 border-l-4 ${SEV_BORDER[sev] ?? "border-l-white/20"} transition-all hover:border-white/20`}
              >
                <CardContent className="p-4 space-y-3">
                  <div className="flex items-start justify-between gap-3">
                    <div className="flex items-center gap-2 flex-wrap">
                      <Badge
                        className={`text-xs border flex items-center gap-1 ${SEV_BADGE[sev] ?? "bg-gray-500/15 text-gray-400 border-gray-500/40"}`}
                      >
                        {SEV_ICON[sev]}
                        {item.severity.toUpperCase()}
                      </Badge>
                      <Badge className="text-xs border bg-white/5 text-white/50 border-white/10">
                        {item.category}
                      </Badge>
                    </div>
                    <span className="text-xs text-white/40 whitespace-nowrap shrink-0">
                      {timeAgo(item.published_at)}
                    </span>
                  </div>

                  <p className="text-sm font-semibold text-white/90 leading-snug">
                    {item.title}
                  </p>

                  {item.ai_summary && (
                    <p className="text-xs text-white/50 leading-relaxed line-clamp-3 whitespace-pre-wrap">
                      {item.ai_summary}
                    </p>
                  )}

                  <div className="flex items-center gap-2 pt-1">
                    <Button
                      size="sm"
                      className="h-7 text-xs bg-cyan-500/10 text-cyan-400 border border-cyan-500/30 hover:bg-cyan-500/20"
                      onClick={() => {
                        setSummaryItem(item);
                        setDialogOpen(true);
                      }}
                    >
                      <Sparkles className="w-3 h-3 mr-1.5" />
                      View Full Summary
                    </Button>
                    <Button
                      asChild
                      size="sm"
                      className="h-7 text-xs bg-white/5 text-white/70 border border-white/10 hover:bg-white/10 hover:text-white"
                    >
                      <a href={item.link} target="_blank" rel="noopener noreferrer">
                        <ExternalLink className="w-3 h-3 mr-1.5" />
                        View Article →
                      </a>
                    </Button>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      <AISummaryDialog
        item={summaryItem}
        open={dialogOpen}
        onClose={() => setDialogOpen(false)}
      />
    </div>
  );
}

